stageCss:
#stage .kf-scene{ position:relative; width:100%; height:100%; display:flex; flex-direction:column; gap:14px; }

/* ============================== TOP STRIP ============================== */
#stage .kf-top{
  height:78px; flex-shrink:0; display:flex; align-items:center; gap:14px;
  padding:0 22px; border-radius:20px; white-space:nowrap;
  background:rgba(20,27,43,.78); border:1.5px solid var(--border);
}
#stage .kf-mark{
  width:46px; height:46px; border-radius:13px; flex-shrink:0;
  display:flex; align-items:center; justify-content:center;
  background:rgba(58,160,255,.14); border:1.5px solid rgba(58,160,255,.42); color:var(--accent-1);
}
#stage .kf-mark svg{ width:25px; height:25px; }
#stage .kf-app{
  color:var(--text-primary); font-family:var(--font-mono); font-size:21px; font-weight:600;
  overflow:hidden; text-overflow:ellipsis; min-width:0;
}
#stage .kf-ops{ margin-left:auto; flex-shrink:0; display:flex; align-items:baseline; gap:8px; }
#stage .kf-ops b{
  color:#fff; font-family:var(--font-mono); font-size:28px; font-weight:700;
  transition:color .3s ease;
}
#stage .kf-ops.bad b{ color:var(--danger); }
#stage .kf-ops.ok b{ color:var(--success); }
#stage .kf-ops i{ color:var(--text-dim); font-size:18px; font-weight:600; font-style:normal; }
#stage .kf-verdict{
  flex-shrink:0; display:flex; align-items:center; gap:8px; padding:7px 14px; border-radius:100px;
  border:1.5px solid var(--border); background:rgba(14,20,32,.7);
  transition:border-color .3s ease, background .3s ease;
}
#stage .kf-verdict i{
  width:10px; height:10px; border-radius:50%; background:var(--text-dim);
  animation:msd-breathe 2s ease-in-out infinite;
}
#stage .kf-verdict b{ color:var(--text-dim); font-family:var(--font-mono); font-size:18px; font-weight:700; }
#stage .kf-verdict.on{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.12); }
#stage .kf-verdict.on i{ background:var(--success); box-shadow:0 0 12px var(--success); }
#stage .kf-verdict.on b{ color:var(--success); }

/* ============================= SCENE STACK ============================= */
#stage .kf-body{ position:relative; flex:1; min-height:0; }
#stage .kf-sc{
  position:absolute; inset:0; opacity:0; transform:scale(.986); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}
#stage .kf-sc.on{ opacity:1; transform:none; }
#stage .kf-sc.whip{ animation:kf-whip .44s cubic-bezier(.19,1,.22,1); }

#stage .kf-board{ display:flex; flex-direction:column; gap:14px; height:100%; }

/* ---------------------------------------------------------- the claim ---- */
#stage .kf-claim{
  height:172px; flex-shrink:0; display:flex; flex-direction:column; justify-content:center; gap:11px;
  padding:18px 24px; border-radius:26px;
  background:radial-gradient(circle at 12% 0%, rgba(58,160,255,.14), transparent 62%), rgba(20,27,43,.7);
  border:2px solid rgba(58,160,255,.45);
  transition:box-shadow .3s ease, border-color .3s ease;
}
#stage .kf-claim.hot{ box-shadow:0 0 0 1px rgba(58,160,255,.25), 0 0 60px rgba(58,160,255,.16); }
#stage .kf-claim-q{
  align-self:flex-start; padding:6px 15px; border-radius:8px;
  background:rgba(58,160,255,.18); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .kf-claim-t{ color:#fff; font-size:33px; font-weight:800; letter-spacing:-.6px; line-height:1.15; }
#stage .kf-claim-s{
  color:var(--text-dim); font-family:var(--font-mono); font-size:19px; font-weight:600;
  white-space:nowrap; overflow:hidden; text-overflow:ellipsis; transition:color .3s ease;
}
#stage .kf-claim-s.ok{ color:var(--success); }
#stage .kf-claim-s.warn{ color:var(--warn); }

/* --------------------------------------------------------- the two needs -- */
#stage .kf-cols{ flex:1; min-height:0; display:flex; gap:14px; }
#stage .kf-col{
  flex:1; min-width:0; display:flex; flex-direction:column; gap:11px;
  padding:16px 15px; border-radius:26px;
  background:rgba(20,27,43,.6); border:2px solid var(--border);
  transition:border-color .3s ease, box-shadow .3s ease, opacity .3s ease, filter .3s ease;
}
#stage .kf-col.work{ border-color:rgba(58,160,255,.42); }
#stage .kf-col.log{ border-color:rgba(34,211,238,.42); }
#stage .kf-col.work.lead{ box-shadow:0 0 0 1px rgba(58,160,255,.24), 0 0 56px rgba(58,160,255,.16); }
#stage .kf-col.log.lead{ box-shadow:0 0 0 1px rgba(34,211,238,.24), 0 0 56px rgba(34,211,238,.16); }
#stage .kf-col.fade{ opacity:.45; filter:saturate(.35); }
#stage .kf-col-h{ display:flex; align-items:center; gap:11px; }
#stage .kf-col-ic{ font-size:28px; flex-shrink:0; }
#stage .kf-col-h b{ color:#fff; font-size:24px; font-weight:800; letter-spacing:-.4px; white-space:nowrap; }
#stage .kf-col-v{
  align-self:flex-start; padding:6px 14px; border-radius:100px; white-space:nowrap;
  border:1.5px solid var(--border); background:rgba(14,20,32,.7); color:var(--text-dim);
  font-family:var(--font-mono); font-size:16px; font-weight:700; letter-spacing:1px;
  transition:border-color .3s ease, background .3s ease, color .3s ease;
}
#stage .kf-col.work .kf-col-v.on{ border-color:rgba(58,160,255,.5); background:rgba(58,160,255,.14); color:var(--accent-1); }
#stage .kf-col.log .kf-col-v.on{ border-color:rgba(34,211,238,.5); background:rgba(34,211,238,.14); color:var(--accent-cyan); }
#stage .kf-col-list{ display:flex; flex-direction:column; gap:9px; }
#stage .kf-r{
  display:flex; align-items:center; gap:10px;
  padding:11px 12px; border-radius:12px; white-space:nowrap; overflow:hidden;
  background:rgba(14,20,32,.72); border:1.5px solid var(--border); color:var(--text-primary);
  font-family:var(--font-mono); font-size:16px; font-weight:600;
}
#stage .kf-r i{ font-style:normal; font-size:15px; flex-shrink:0; }

/* ------------------------------------------------------------ the facts -- */
#stage .kf-fact{ position:relative; height:184px; flex-shrink:0; }
#stage .kf-f{
  position:absolute; inset:0; opacity:0; pointer-events:none;
  display:flex; flex-direction:column; align-items:center; justify-content:center; gap:12px;
  padding:16px 20px; border-radius:24px;
  background:rgba(20,27,43,.6); border:1.5px solid var(--border);
  transition:opacity .3s ease;
}
#stage .kf-f.on{ opacity:1; }
#stage .kf-f-t{ color:#fff; font-size:22px; font-weight:800; letter-spacing:-.3px; white-space:nowrap; }
#stage .kf-f-b{
  padding:7px 16px; border-radius:100px; white-space:nowrap;
  border:1.5px solid rgba(240,166,74,.5); background:rgba(240,166,74,.12); color:var(--warn);
  font-family:var(--font-mono); font-size:17px; font-weight:700;
}
#stage .kf-f-b.ok{ border-color:rgba(63,185,80,.5); background:rgba(63,185,80,.14); color:var(--success); }
#stage .kf-f-b.bad{ border-color:rgba(244,74,106,.55); background:rgba(244,74,106,.14); color:var(--danger); }
/* Eight partitions, eight slots — the cap made literal. */
#stage .kf-parts{ display:flex; align-items:center; gap:8px; }
#stage .kf-parts i{
  display:block; width:64px; height:30px; border-radius:8px;
  background:rgba(34,211,238,.18); border:1.5px solid rgba(34,211,238,.5);
}
#stage .kf-parts b{
  display:none; padding:7px 12px; border-radius:9px; white-space:nowrap;
  background:rgba(244,74,106,.16); border:1.5px solid rgba(244,74,106,.5); color:var(--danger);
  font-family:var(--font-mono); font-size:16px; font-weight:800;
}
#stage .kf-parts b.on{ display:block; animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }
#stage .kf-conf{ display:flex; flex-direction:column; gap:5px; align-items:center; }
#stage .kf-conf-l{
  color:var(--code-str); font-family:var(--font-mono); font-size:17px; font-weight:600; white-space:nowrap;
}
#stage .kf-chips{ display:flex; align-items:center; gap:9px; }
#stage .kf-chips i{
  padding:9px 14px; border-radius:11px; white-space:nowrap; font-style:normal;
  background:rgba(244,74,106,.1); border:1.5px solid rgba(244,74,106,.35); color:#ffd0d9;
  font-family:var(--font-mono); font-size:16px; font-weight:600;
}

#stage .kf-strip{
  height:72px; flex-shrink:0; display:flex; align-items:center; gap:16px;
  padding:0 22px; border-radius:20px;
  background:rgba(20,27,43,.7); border:1.5px solid var(--border);
  transition:border-color .3s ease, background .3s ease;
}
#stage .kf-strip b{
  padding:6px 15px; border-radius:8px; flex-shrink:0;
  background:rgba(58,160,255,.16); color:var(--accent-1);
  font-family:var(--font-mono); font-size:18px; font-weight:800; letter-spacing:2px;
}
#stage .kf-strip span{ color:var(--text-primary); font-size:22px; font-weight:600; line-height:1.3; }
#stage .kf-strip.bad{ border-color:rgba(244,74,106,.5); background:rgba(244,74,106,.1); }
#stage .kf-strip.bad b{ background:rgba(244,74,106,.2); color:var(--danger); }
#stage .kf-strip.good{ border-color:rgba(63,185,80,.45); background:rgba(63,185,80,.09); }
#stage .kf-strip.good b{ background:rgba(63,185,80,.2); color:var(--success); }

/* ======================= SCENE 2 · THE THREE OPTIONS =================== */
#stage .kf-split{ display:flex; gap:14px; height:100%; }
#stage .kf-c{
  flex:1; min-width:0; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px;
  padding:22px 13px; border-radius:26px; text-align:center;
}
#stage .kf-c.sb{
  background:radial-gradient(circle at 50% 0%, rgba(58,160,255,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(58,160,255,.55);
}
#stage .kf-c.eh{
  background:radial-gradient(circle at 50% 0%, rgba(34,211,238,.14), transparent 62%), rgba(20,27,43,.6);
  border:2px solid rgba(34,211,238,.55);
}
#stage .kf-c.k{ background:rgba(20,27,43,.6); border:2px solid rgba(139,149,167,.35); }
#stage .kf-c-h{ font-family:var(--font-mono); font-size:17px; font-weight:800; letter-spacing:1.4px; white-space:nowrap; }
#stage .kf-c.sb .kf-c-h{ color:var(--accent-1); }
#stage .kf-c.eh .kf-c-h{ color:var(--accent-cyan); }
#stage .kf-c.k .kf-c-h{ color:var(--text-dim); }
#stage .kf-c-ic{ font-size:50px; line-height:1; }
#stage .kf-c-list{ width:100%; display:flex; flex-direction:column; gap:9px; }
#stage .kf-row{
  padding:12px 8px; border-radius:12px;
  background:rgba(14,20,32,.7); border:1.5px solid var(--border); color:var(--text-dim);
  font-size:19px; font-weight:600; line-height:1.25;
}
#stage .kf-row b{ color:#fff; font-weight:800; }
#stage .kf-c-x{
  width:100%; padding:12px 8px; border-radius:13px;
  background:rgba(139,149,167,.1); border:1.5px solid rgba(139,149,167,.3); color:var(--text-dim);
  font-family:var(--font-mono); font-size:16px; font-weight:700; line-height:1.3;
}
#stage .kf-c-x.hot{ background:rgba(63,185,80,.12); border-color:rgba(63,185,80,.45); color:var(--success); }

/* ========================== SCENE 3 · THE PAYOFF ======================= */
#stage .kf-final{
  height:100%; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:18px;
  text-align:center;
}
#stage .kf-badge{
  width:130px; height:130px; border-radius:36px; font-size:60px;
  display:flex; align-items:center; justify-content:center;
  background:linear-gradient(160deg, rgba(58,160,255,.28), rgba(34,211,238,.14));
  border:2px solid rgba(58,160,255,.6);
  box-shadow:0 0 0 1px rgba(58,160,255,.3), 0 0 80px rgba(58,160,255,.3);
  animation:msd-breathe 2.4s ease-in-out infinite;
}
#stage .kf-badge-l{ color:var(--accent-1); font-family:var(--font-mono); font-size:20px; font-weight:800; letter-spacing:3px; }
#stage .kf-fin-h{ color:#fff; font-size:62px; font-weight:900; line-height:1.12; letter-spacing:-2px; }
#stage .kf-fin-h em{ font-style:normal; color:var(--accent-cyan); }
#stage .kf-fin-row{ display:flex; flex-wrap:wrap; justify-content:center; gap:12px; }
#stage .kf-fin-p{
  padding:12px 20px; border-radius:100px; white-space:nowrap;
  background:rgba(20,27,43,.8); border:1.5px solid rgba(58,160,255,.42); color:var(--text-primary);
  font-size:21px; font-weight:700;
}
#stage .kf-save{
  margin-top:8px; padding:18px 26px; border-radius:20px; max-width:840px;
  background:linear-gradient(90deg, rgba(58,160,255,.2), rgba(34,211,238,.1));
  border:1.5px solid rgba(58,160,255,.55); color:#fff;
  font-size:26px; font-weight:700; line-height:1.35;
}
#stage .kf-save.ping{ animation:msd-punch .4s cubic-bezier(.22,1,.36,1); }

/* ============================== KEYFRAMES ============================== */
@keyframes kf-whip{
  0%{ transform:translateX(220px) scale(1.04); filter:blur(16px); opacity:0; }
  55%{ filter:blur(3px); opacity:1; }
  100%{ transform:none; filter:blur(0); opacity:1; }
}

